import {normalizePlayer} from './player-profile.mjs';
import {FACTIONS} from './conquest-data.mjs';
import {snapshot} from './conquest-model.mjs';
export class ConquestNetwork {
 constructor(controller){this.c=controller;this.peer=null;this.host=null;this.members=[];this.connections=new Map();this.guest=false;this.status='';this.closed=false;this.sequence=0;this.lastSeq=new Map();this.rate=new Map()}
 clean(){clearInterval(this.handshake);clearTimeout(this.connectTimer);this.closed=true;this.peer?.destroy();this.peer=null;this.host=null;this.members=[];this.connections.clear();this.guest=false;this.sequence=0;this.lastSeq.clear();this.rate.clear()}
 refresh(){if(this.c.g.page==='conquest'&&!this.c.active)this.c.g.render()}
 fail(message){this.status=message;this.c.g.toast(message);this.refresh()}
 available(){if(!window.Peer){this.fail('Le service de connexion est indisponible. Le mode solo reste disponible.');return false}return this.c.g.requireStarter()}
 create(){if(!this.available())return;this.clean();this.closed=false;this.status='Ouverture du salon…';this.peer=new window.Peer();this.peer.on('open',id=>{this.members=[{pid:id,...normalizePlayer(this.c.g.state.player),faction:this.c.settings.faction}];this.status='Salon prêt. Partage son code.';this.refresh()});this.peer.on('error',e=>this.fail('Connexion : '+e.type));this.peer.on('connection',conn=>{conn.on('open',()=>{if(this.connections.size>=3||this.c.active){conn.send({type:'reject',message:'Le salon est complet ou la campagne a commencé.'});setTimeout(()=>conn.close(),300);return}this.connections.set(conn.peer,conn)});conn.on('data',data=>this.receiveGuest(conn,data));conn.on('close',()=>{this.connections.delete(conn.peer);this.members=this.members.filter(m=>m.pid!==conn.peer);if(this.c.active){const p=this.c.s.players.find(p=>p.pid===conn.peer);if(p){p.ai=true;this.c.g.toast(p.name+' a quitté la partie. Son camp passe à l’IA.')}}else{this.lobby();this.refresh()}})});this.refresh()}
 join(code){if(!this.available()||!String(code).trim())return this.fail('Entre le code du salon.');this.clean();this.closed=false;this.guest=true;this.status='Connexion au salon…';this.peer=new window.Peer();this.peer.on('open',()=>{this.host=this.peer.connect(String(code).trim(),{reliable:true});const hello=()=>{if(this.host?.open)this.host.send({type:'hello',profile:normalizePlayer(this.c.g.state.player),faction:this.c.settings.faction})};this.host.on('open',()=>{hello();this.handshake=setInterval(hello,1000)});this.host.on('error',()=>this.fail('Connexion au salon impossible. Ferme le salon puis réessaie.'));this.connectTimer=setTimeout(()=>{clearInterval(this.handshake);if(!this.members.length)this.fail('Connexion trop lente. Ferme le salon puis réessaie.')},20000);this.host.on('data',d=>this.receiveHost(d));this.host.on('close',()=>{if(this.closed)return;this.fail('L’hôte a fermé la connexion.');if(this.c.active)this.c.connectionLost()})});this.peer.on('error',e=>this.fail('Connexion : '+e.type));this.refresh()}
 faction(pid,requested){if(!FACTIONS.some(f=>f.id===requested))return;const member=this.members.find(m=>m.pid===pid);if(!member)return;const used=new Set(this.members.filter(m=>m!==member).map(m=>m.faction));member.faction=used.has(requested)?FACTIONS.find(f=>!used.has(f.id)).id:requested;this.lobby();this.refresh()}
 lobby(){this.broadcast({type:'lobby',members:this.members,settings:this.c.settings})}
 broadcast(data){for(const conn of this.connections.values())if(conn.open)conn.send(data)}
 start(s){this.broadcast({type:'begin',state:snapshot(s)})}
 sync(){if(this.connections.size&&this.c.s)this.broadcast({type:'state',state:snapshot(this.c.s)})}
 send(command){if(!this.host?.open){this.fail('Connexion à l’hôte perdue.');return null}const seq=++this.sequence;this.host.send({type:'command',id:this.c.s.id,seq,command});return seq}
 chooseFaction(faction){if(this.guest)this.host?.send({type:'faction',faction});else this.faction(this.peer.id,faction)}
 receiveGuest(conn,d){if(!this.connections.has(conn.peer)||!d||typeof d!=='object')return;if(d.type==='hello'&&!this.c.active){if(this.members.some(m=>m.pid===conn.peer)){this.lobby();return;}const used=new Set(this.members.map(m=>m.faction)),faction=FACTIONS.find(f=>f.id===d.faction&&!used.has(f.id))||FACTIONS.find(f=>!used.has(f.id));this.members.push({pid:conn.peer,...normalizePlayer(d.profile),faction:faction.id});this.lobby();this.refresh()}if(d.type==='faction'&&!this.c.active)this.faction(conn.peer,d.faction);if(d.type==='command'&&this.c.active&&d.id===this.c.s.id&&Number.isInteger(d.seq)&&d.seq>(this.lastSeq.get(conn.peer)||0)){const now=performance.now(),rate=this.rate.get(conn.peer)||{at:now,count:0};if(now-rate.at>1000){rate.at=now;rate.count=0}if(++rate.count>12){conn.send({type:'ack',id:this.c.s.id,seq:d.seq,result:{ok:false,message:'Patiente une seconde avant un nouvel ordre.'}});return;}this.rate.set(conn.peer,rate);this.lastSeq.set(conn.peer,d.seq);const p=this.c.s.players.find(p=>p.pid===conn.peer);if(!p)return;const result=this.c.issue(d.command,p.id);conn.send({type:'ack',id:this.c.s.id,seq:d.seq,result});if(result.ok)this.sync()}}
 receiveHost(d){if(!d||typeof d!=='object')return;if(d.type==='reject')this.fail(String(d.message).slice(0,150));if(d.type==='lobby'&&!this.c.active&&Array.isArray(d.members)){clearInterval(this.handshake);clearTimeout(this.connectTimer);this.members=d.members.slice(0,4).map(m=>({pid:String(m.pid),...normalizePlayer(m),faction:FACTIONS.some(f=>f.id===m.faction)?m.faction:'rocket'}));const own=this.members.find(m=>m.pid===this.peer.id);this.c.settings={...this.c.settings,...d.settings,faction:own?.faction||this.c.settings.faction};this.status='Prêt. L’hôte choisit la région et lance la campagne.';this.refresh()}if(d.type==='begin'&&!this.c.active)this.c.receiveStart(d.state);if(d.type==='state'&&this.c.active&&this.c.s.id===d.state?.id)this.c.receiveState(d.state);if(d.type==='ack'&&this.c.active&&d.id===this.c.s.id)this.c.acknowledge(d.seq,d.result);if(d.type==='notice')this.c.g.toast(String(d.message).slice(0,180))}
}
